            </div>

            <div class="stat-item">
                <div class="stat-label">
                    <span><span class="icon">☠</span>堕落值</span>
                    <span class="stat-value" id="corruption-value">{{get_message_variable::stat_data.临时角色宏.堕落值}}/100</span>
                </div>
                <div class="stat-bar">
                    <div class="stat-fill" id="corruption-bar" style="width: {{get_message_variable::stat_data.临时角色宏.堕落值}}%"></div>
